CREATE TABLE instances(id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE profiles(instance_id TEXT NOT NULL, id TEXT NOT NULL, display_name TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(instance_id,id));
CREATE TABLE departments(id TEXT PRIMARY KEY, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active');
CREATE UNIQUE INDEX active_department_name ON departments(name) WHERE status='active';
CREATE TABLE users(id TEXT PRIMARY KEY, name TEXT NOT NULL, platform TEXT NOT NULL DEFAULT 'feishu', external_id TEXT NOT NULL, department_id TEXT REFERENCES departments(id), profile TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'active', UNIQUE(platform,external_id));
CREATE TABLE department_membership(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), department_id TEXT NOT NULL REFERENCES departments(id), valid_from TEXT NOT NULL, valid_to TEXT);
CREATE INDEX membership_user ON department_membership(user_id,valid_from);
CREATE TABLE profile_user_mapping(instance_id TEXT NOT NULL, profile_id TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), valid_from TEXT NOT NULL, valid_to TEXT, PRIMARY KEY(instance_id,profile_id,user_id,valid_from));
CREATE TABLE sessions(session_key TEXT PRIMARY KEY, instance_id TEXT NOT NULL, profile_id TEXT NOT NULL, source_session_id TEXT NOT NULL, user_id TEXT, department_id TEXT, started_at TEXT NOT NULL, last_at TEXT NOT NULL, platform TEXT NOT NULL DEFAULT 'unknown', UNIQUE(instance_id,profile_id,source_session_id));
CREATE TABLE turns(turn_key TEXT PRIMARY KEY, session_key TEXT NOT NULL REFERENCES sessions(session_key), source_turn_id TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE model_prices(id TEXT PRIMARY KEY, provider TEXT NOT NULL, model TEXT NOT NULL, input TEXT NOT NULL, cached TEXT NOT NULL, output TEXT NOT NULL, valid_from TEXT NOT NULL, valid_to TEXT, starts_at TEXT NOT NULL, ends_at TEXT, enabled INTEGER NOT NULL DEFAULT 1, currency TEXT NOT NULL DEFAULT 'USD', tokens_per_unit INTEGER NOT NULL DEFAULT 1000000, CHECK(valid_to IS NULL OR valid_to>=valid_from));
CREATE INDEX price_lookup ON model_prices(provider,model,starts_at,ends_at);
CREATE TABLE llm_requests(event_key TEXT PRIMARY KEY, instance_id TEXT NOT NULL, profile_id TEXT NOT NULL, source_event_id TEXT NOT NULL, session_key TEXT NOT NULL REFERENCES sessions(session_key), api_request_id TEXT NOT NULL, attempt_no INTEGER NOT NULL DEFAULT 0, request_kind TEXT NOT NULL DEFAULT 'main', provider TEXT NOT NULL, model TEXT NOT NULL, user_id TEXT, department_id TEXT, occurred_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('success','failed')), input_total_tokens INTEGER CHECK(input_total_tokens>=0), cached_input_tokens INTEGER CHECK(cached_input_tokens>=0), uncached_input_tokens INTEGER CHECK(uncached_input_tokens>=0), output_tokens INTEGER CHECK(output_tokens>=0), total_tokens INTEGER CHECK(total_tokens>=0), duration_ms INTEGER CHECK(duration_ms>=0), price_id TEXT REFERENCES model_prices(id), cost_micro_usd INTEGER CHECK(cost_micro_usd>=0), cost_source TEXT NOT NULL DEFAULT 'unknown', input_cost_micro_usd INTEGER, cached_cost_micro_usd INTEGER, output_cost_micro_usd INTEGER, CHECK(cached_input_tokens IS NULL OR input_total_tokens IS NULL OR cached_input_tokens<=input_total_tokens), UNIQUE(instance_id,profile_id,source_event_id));
CREATE INDEX request_time ON llm_requests(occurred_at);
CREATE INDEX request_department ON llm_requests(department_id,occurred_at);
CREATE INDEX request_user ON llm_requests(user_id,occurred_at);
CREATE INDEX request_model ON llm_requests(provider,model,occurred_at);
CREATE INDEX request_session ON llm_requests(session_key,occurred_at);
CREATE TABLE tool_calls(event_key TEXT PRIMARY KEY, instance_id TEXT NOT NULL, profile_id TEXT NOT NULL, source_event_id TEXT NOT NULL, session_key TEXT NOT NULL REFERENCES sessions(session_key), user_id TEXT, department_id TEXT, tool_id TEXT NOT NULL, tool_name TEXT NOT NULL, tool_type TEXT NOT NULL CHECK(tool_type IN ('mcp','local','unknown')), mcp_server_id TEXT, status TEXT NOT NULL CHECK(status IN ('success','failed')), duration_ms INTEGER CHECK(duration_ms>=0), occurred_at TEXT NOT NULL, UNIQUE(instance_id,profile_id,source_event_id));
CREATE INDEX tool_scope ON tool_calls(department_id,occurred_at,tool_type);
CREATE INDEX tool_session ON tool_calls(session_key,occurred_at);
CREATE TABLE mcp_tools(server_id TEXT NOT NULL, tool_id TEXT NOT NULL, display_name TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(server_id,tool_id));
CREATE TABLE event_inbox(event_key TEXT PRIMARY KEY, type TEXT NOT NULL, received_at TEXT NOT NULL, status TEXT NOT NULL, schema_version INTEGER NOT NULL DEFAULT 1, error_code TEXT);
CREATE TABLE audit_access_logs(id TEXT PRIMARY KEY, actor_id TEXT NOT NULL, action TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT NOT NULL, occurred_at TEXT NOT NULL, result TEXT NOT NULL, request_id TEXT NOT NULL);
CREATE TABLE plugin_settings(key TEXT PRIMARY KEY, value_json TEXT NOT NULL);
